export function projectCoords(lat, lng) {
  const minLon = -100.20, maxLon = -97.10;
  const minLat = 22.10, maxLat = 27.75;
  const midLatRad = ((minLat + maxLat) / 2 * Math.PI) / 180;
  const cosMidLat = Math.cos(midLatRad);
  const targetWidth = 620, targetHeight = 940, padding = 25;
  const availableW = targetWidth - 2 * padding, availableH = targetHeight - 2 * padding;
  const spanX = (maxLon - minLon) * cosMidLat, spanY = maxLat - minLat;
  const scale = Math.min(availableW / spanX, availableH / spanY);
  const renderW = spanX * scale, renderH = spanY * scale;
  const offsetX = (targetWidth - renderW) / 2, offsetY = (targetHeight - renderH) / 2;
  const x = offsetX + (lng - minLon) * cosMidLat * scale;
  const y = offsetY + (maxLat - lat) * scale;
  return { x: Number(x.toFixed(1)), y: Number(y.toFixed(1)) };
}

